CREATE TABLE "safety_assertion_documents" ("id" uuid NOT NULL, "digest_algorithm" character varying NOT NULL, "digest" character varying NOT NULL, "document_ref" character varying NOT NULL, "origin" character varying NOT NULL, "collector" character varying NOT NULL, "source_authority" character varying NULL, "received_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "safetyassertiondocument_digest_algorithm_digest" ON "safety_assertion_documents" ("digest_algorithm", "digest");
CREATE TABLE "safety_assertions" ("id" uuid NOT NULL, "assertion_id" character varying NOT NULL, "content_hash" character varying NOT NULL, "safety_relevance" character varying NOT NULL, "classification_scheme" character varying NULL, "classification_value" character varying NULL, "rationale" text NOT NULL, "decision_status" character varying NOT NULL, "reviewer" character varying NULL, "asserted_at" timestamptz NOT NULL, "valid_until" timestamptz NULL, "product_purl" text NOT NULL, "component_purl" text NOT NULL, "component_bom_ref" character varying NULL, "component_digest_algorithm" character varying NULL, "component_digest" character varying NULL, "evidence" jsonb NOT NULL, "document_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "safety_assertions_safety_assertion_documents_assertions" FOREIGN KEY ("document_id") REFERENCES "safety_assertion_documents" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "safetyassertion_document_id_assertion_id" ON "safety_assertions" ("document_id", "assertion_id");
CREATE INDEX "safetyassertion_product_purl" ON "safety_assertions" ("product_purl");
CREATE INDEX "safetyassertion_component_purl" ON "safety_assertions" ("component_purl");
CREATE INDEX "safetyassertion_safety_relevance_decision_status" ON "safety_assertions" ("safety_relevance", "decision_status");
